Dim2.new(0,16,0,37);Ql.TextWrapped=true;Ql.ZIndex=71;fl=Instance.new("Frame");fl.Size=UDim2.new(1,-32,0,32);fl.Position=UDim2.new(0,16,0,65);fl.BackgroundTransparency=1;fl.BorderSizePixel=0;fl.ZIndex=72;fl.Parent=Pl;local rl=Instance.new("UIListLayout");rl.FillDirection=Enum.FillDirection.Horizontal;rl.Padding=UDim.new(0,6);rl.Parent=fl;local Wl=Instance.new("ScrollingFrame");Wl.Size=UDim2.new(1,-28,1,-174);Wl.Position=UDim2.new(0,14,0,106);Wl.BackgroundTransparency=1;Wl.BorderSizePixel=0;Wl.CanvasSize=UDim2.new(0,0,0,0);Wl.AutomaticCanvasSize=Enum.AutomaticSize.Y;Wl.ZIndex=71;Wl.Parent=Pl;rl=Instance.new("UIListLayout");rl.Padding=UDim.new(0,6);rl.Parent=Wl;rl=Instance.new("UIPadding");rl.PaddingTop=UDim.new(0,2);rl.PaddingBottom=UDim.new(0,10);rl.PaddingRight=UDim.new(0,4);rl.Parent=Wl;mH(Wl,5);local mH={Quick={},Advanced={},Help={}};local function Al(wl,pl,Fl,Ll)local zl=Instance.new("Frame");zl.Size=UDim2.new(1,-4,0,0);zl.AutomaticSize=Enum.AutomaticSize.Y;zl.BackgroundColor3=C.ROW;zl.BackgroundTransparency=0.04;zl:SetAttribute("CBGlassExclude",true);zl.BorderSizePixel=0;zl.ZIndex=72;zl.Parent=Wl;P(8,zl);Q(1,Ll or C.BORDER,zl);f(10,10,13,11,zl);local ml=Instance.new("UIListLayout");ml.Padding=UDim.new(0,4);ml.Parent=zl;ml=XH(zl,pl,12,Ll or C.ACCENT,C.FONT_BOLD);ml.Size=UDim2.new(1,0,0,18);ml.ZIndex=73;Ll=XH(zl,Fl,11,C.TEXT,C.FONT);Ll.Size=UDim2.new(1,0,0,0);Ll.AutomaticSize=Enum.AutomaticSize.Y;Ll.TextWrapped=true;Ll.TextYAlignment=Enum.TextYAlignment.Top;Ll.LineHeight=1.05;Ll.ZIndex=73;zl.Visible=false;table.insert(mH[wl],zl);end;Al("Quick","1  -  PICK A SLOT","Choose one of the five slots and rename it for the combo you are building. Each slot saves automatically.",Color3.fromRGB(90,160,255));Al("Quick","2  -  ENABLE BLOCK 1","Turn Block 1 ON. Start with only one enabled block so a setup mistake is easy to find.",Color3.fromRGB(90,160,255));Al("Quick","3  -  CHOOSE WEAPON AND SKILL","Pick Melee, Fruit, Sword, or Gun, then select Z, X, C, V, or F. Smart finds and equips that category automatically.",Color3.fromRGB(90,160,255));Al("Quick","4  -  CHOOSE THE CAST MODE","Use TAP for a normal press, HOLD for a charged move, or TRANSFORM on a Fruit V block to enter a supported Fruit form safely.",Color3.fromRGB(90,160,255));Al("Quick","5  -  RUN AND BUILD GRADUALLY","Press RUN SMART MACRO. After Block 1 works, enable Block 2 and test again. Enabled blocks always run in number order.",Color3.fromRGB(90,160,255));Al("Advanced","BACKUP SKILL","Adds a second choice to the same block. If the main skill is on cooldown, Smart tries the backup. If neither is ready, it skips that block.",Color3.fromRGB(245,190,35));Al("Advanced","JUMPS AFTER SKILL","Choose 1 to 5 jumps when the next skill needs more height. The jumps begin only after this block's primary or backup skill is accepted. Leave it at None for normal timing.",Color3.fromRGB(90,160,255));Al("Advanced","SORU AIM","Place Soru before Block 1 or after a block. The macro's Soru action aims automatically and does not require the standalone Soru Aimbot toggle or its keybind. No target or an active Soru cooldown is skipped safely.",Color3.fromRGB(170,95,255));Al("Advanced","WEAPON M1","Choose Melee, Fruit, Sword, or Gun, select 1 to 6 attacks, and place the action before Block 1 or after a block. Fruit M1 follows the equipped fruit's live awakening or transformation requirements.",Color3.fromRGB(225,80,85));Al("Advanced","RACE V3","Place your current race V3 before Block 1 or after a block. Enabling this action disables Auto V3 and Smart V3 so only the macro controls when V3 is requested.",Color3.fromRGB(75,205,190));Al("Advanced","AUTOMATIC TIMING","Smart waits for live cooldown and cast confirmation, then advances as soon as the game is ready. Jumps After Skill is the only optional positioning step before the next block. One missed input is retried; an accepted cast and its jumps are never duplicated.");Al("Advanced","FRUIT TRANSFORM","Set Weapon to Fruit, Skill to V, then choose TRANSFORM. If already transformed, Smart skips V. Otherwise it confirms the real form, waits for Busy/Stun and Fruit controls to clear, then immediately continues. Use TAP when V should behave normally or end/change a form.",Color3.fromRGB(245,190,35));Al("Advanced","SUPPORTED TRANSFORMS","TRANSFORM supports Dragon, Gas, Kitsune, Leopard, Mammoth, Phoenix, Tiger, T-Rex, Venom, Yeti, Empyrean, Fiend, and Werewolf. Other Fruit V abilities are rejected instead of being cast as a transformation.",Color3.fromRGB(245,190,35));Al("Advanced","AIMBOT, CAMLOCK, AND RANGE","Macro abilities use the normal casting path, so your Skill Aimbot, prediction, CamLock, targeting, blacklist, and ability reach settings still apply.");Al("Help","RUNNING AND STOPPING","Use RUN SMART MACRO, the Macro Play / Stop keybind, or the on-screen MACRO button. Use the same control again to stop. Macro Status is display-only.");Al("Help","PC, MOBILE, AND HOTBAR ORDER","The same slot and cast modes work on PC, Classic mobile, and Modern mobile. Smart finds weapons by category, so rearranging hotbar slots does not break it.");Al("Help","COPY, IMPORT, AND RESET","Copy shares only the active slot, including TAP/HOLD/TRANSFORM modes, per-block jumps, and Soru, M1, and V3 placements. Import replaces only that slot; Reset clears only that slot.",Color3.fromRGB(90,160,255));Al("Help","IF THE MACRO STOPS","Read the notification and test one block at a time. Confirm you own the selected item, its cooldown panel is visible, and TRANSFORM is used only with a supported Fruit V.",Color3.fromRGB(235,85,85));Al("Help","SAFE TESTING","Teleport to the Training Dummy. Test Block 1 alone, then add one block at a time so an incorrect weapon, key, or cast mode is obvious.");local wl,pl={},{Quick="Five simple steps to build a working combo from scratch.",Advanced="Add these options only after the basic block sequence works.",Help="Running, sharing, mobile behavior, and quick troubleshooting."};local function Fl(Ll)for zl,ml i